 const total=items.reduce((n,x)=>n+x.m.facts.length,0),found=items.reduce((n,x)=>n+x.m.facts.filter((f,i)=>st.checks['clue'+x.r[0]+'-'+i]).length,0);
 const tabbar='<div class="invest-tabs"><button class="btn '+(tab==='points'?'primary':'')+'" data-tab="points">Pontos de interesse</button><button class="btn '+(tab==='chains'?'primary':'')+'" data-tab="chains">Cadeias</button><button class="btn '+(tab==='quick'?'primary':'')+'" data-tab="quick">Consulta rápida</button></div>';
