const dieSteps=[4,6,8,10,12];
const alanSkills=[['Acrobacia','Fisico',4],['Aptidão (Humanas)','Mente',6],['Atletismo','Fisico',10],['Crime','Fisico',6],['Disciplina','Emocao',6],['Enganação','Emocao',6],['Furtividade','Fisico',4],['Intimidação','Emocao',4],['Intuição','Emocao',4],['Luta','Fisico',4],['Máquinas','Mente',6],['Medicina','Mente',4],['Ocultismo','Mente',4],['Percepção','Mente',8],['Persuasão','Emocao',4],['Pesquisa','Mente',6],['Pontaria','Fisico',4],['Sobrevivência','Mente',4],['Tecnologia','Mente',4],['Vigor','Fisico',6]];
const attrLabels={Fisico:'Físico',Mente:'Mente',Emocao:'Emoção'};
function defaultSheet(name){
 const alan=name==='Alan';
 return {profile:alan?'Executor':'',occupation:alan?'Cientista':'',level:alan?2:'',attributes:{Fisico:alan?6:'',Mente:alan?8:'',Emocao:alan?8:''},pv:alan?10:'',pvMax:alan?10:'',pd:alan?16:'',pdMax:alan?16:'',impeto:0,
 skills:Object.fromEntries(alanSkills.map(x=>[x[0],alan?x[2]:''])),skillAttrs:Object.fromEntries(alanSkills.map(x=>[x[0],x[1]])),
 abilities:alan?'FOCO MENTAL — Quando faz um teste mental, pode gastar 2 PD para receber +4 no teste.\n\nÍMPETO — Possui uma barra com três espaços. Sempre que falha em um teste, preenche um espaço. Pode apagar um espaço preenchido para receber +4 em um teste ou aumentar um atributo em um passo até o fim da cena.':''};
}
function getSheet(name){const k='sheet-data-'+name;if(!st.custom[k])st.custom[k]=JSON.stringify(defaultSheet(name));try{return JSON.parse(st.custom[k])}catch{return defaultSheet(name)}}
function saveSheet(name,d){st.custom['sheet-data-'+name]=JSON.stringify(d);save()}
function optDie(v){return '<option value="">—</option>'+dieSteps.map(n=>'<option value="'+n+'" '+(String(v)===String(n)?'selected':'')+'>d'+n+'</option>').join('')}
function characters(){
 const c=cast.find(x=>x[0]===st.selectedCharacter)||cast[0],d=getSheet(c[0]),selected=st.selectedSkill||'Acrobacia';
 const skills=alanSkills.map(x=>'<div class="sheet-skill"><button data-roll-skill="'+esc(x[0])+'">'+esc(x[0])+' <small>'+esc(attrLabels[d.skillAttrs?.[x[0]]||x[1]])+'</small></button><select data-sheet-skill="'+esc(x[0])+'" data-owner="'+esc(c[0])+'">'+optDie(d.skills?.[x[0]])+'</select></div>').join('');
 const chosen=alanSkills.find(x=>x[0]===selected)||alanSkills[0],baseAttr=d.skillAttrs?.[selected]||chosen[1],cfg=st.custom['test-'+c[0]]?JSON.parse(st.custom['test-'+c[0]]):{};
 const test=st.selectedSkill?'<div class="sheet-test"><h3>Teste: '+esc(selected)+'</h3><div class="sheet-test-grid"><label>Atributo<select id="tc-attr">'+Object.keys(attrLabels).map(k=>'<option value="'+k+'" '+((cfg.attr||baseAttr)===k?'selected':'')+'>'+attrLabels[k]+'</option>').join('')+'</select></label><label>Dado do atributo<select id="tc-ad">'+optDie(cfg.ad||d.attributes?.[cfg.attr||baseAttr])+'</select></label><label>Dado da perícia<select id="tc-sd">'+optDie(cfg.sd||d.skills?.[selected])+'</select></label><label>DT<input id="tc-dt" type="number" value="'+(cfg.dt??7)+'"></label><label>Dados extras<select id="tc-extra"><option value="0">Nenhum</option><option value="1" '+(cfg.extra==1?'selected':'')+'>1 dado</option><option value="2" '+(cfg.extra==2?'selected':'')+'>2 dados</option></select></label><label>Dado extra<select id="tc-ed">'+dieSteps.map(n=>'<option value="'+n+'" '+((cfg.ed||6)===n?'selected':'')+'>d'+n+'</option>').join('')+'</select></label><label>Bônus direto<input id="tc-bonus" type="number" value="'+(cfg.bonus||0)+'"></label></div><div class="row"><button class="btn primary" data-roll-char="'+esc(selected)+'">Rolar teste</button>'+( (cfg.attr||baseAttr)==='Mente'?'<button class="btn" data-focus>Foco Mental (−2 PD, +4)</button>':'')+'<button class="btn" data-impeto '+(Number(d.impeto||0)<1?'disabled':'')+'>Ímpeto (+4) · '+Number(d.impeto||0)+'</button></div><p class="subtle">Dois dados básicos (atributo + perícia), até quatro dados rolados e até três somados. Os ajustes são temporários para este teste.</p></div>':'<p class="sheet-test-empty">Selecione uma perícia para configurar uma rolagem.</p>';
 page('Personagens e NPCs','<div class="sheet-toolbar"><div><label class="subtle">Personagem</label><select class="wide-select" id="character-select">'+cast.map(x=>'<option value="'+esc(x[0])+'" '+(x[0]===c[0]?'selected':'')+'>'+esc(x[0]+' — '+x[1])+'</option>').join('')+'</select></div><div class="row"><input id="new-char" placeholder="Novo personagem"><button class="btn" data-add-char>Adicionar</button></div></div><div class="sheet-card"><div class="sheet-head"><div><small>FICHA DE PERSONAGEM</small><h2>'+esc(c[0])+'</h2><span>'+esc(c[1])+'</span></div><label>Estado<select data-status="'+esc(c[0])+'"><option value="">Não definido</option>'+['Vivo','Ferido','Inconsciente','Morto','Ausente','Acorrentado'].map(x=>'<option '+(st.statuses[c[0]]===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label></div><div class="sheet-fields">'+[['profile','Perfil'],['occupation','Ocupação'],['level','Nível'],['pv','PV atual'],['pvMax','PV máximo'],['pd','PD atual'],['pdMax','PD máximo']].map(x=>'<label>'+x[1]+'<input data-sheet-field="'+x[0]+'" data-owner="'+esc(c[0])+'" value="'+esc(d[x[0]])+'" '+(x[0]==='level'||x[0].startsWith('pv')||x[0].startsWith('pd')?'type="number"':'')+'></label>').join('')+'</div><div class="sheet-block"><h3>Atributos</h3><div class="sheet-attrs">'+Object.keys(attrLabels).map(k=>'<label>'+attrLabels[k]+'<select data-sheet-attr="'+k+'" data-owner="'+esc(c[0])+'">'+optDie(d.attributes?.[k])+'</select></label>').join('')+'</div></div><div class="sheet-block"><h3>Perícias <small>Toque no nome para rolar</small></h3><div class="sheet-skills">'+skills+'</div></div>'+test+'<div class="sheet-block"><h3>Ímpeto</h3><div class="row">'+[0,1,2].map(i=>'<button class="btn '+(i<Number(d.impeto||0)?'primary':'')+'" data-impeto-slot="'+i+'">'+(i<Number(d.impeto||0)?'●':'○')+'</button>').join('')+'<small>Falhas preenchem um espaço; clique para ajustar manualmente.</small></div></div><div class="sheet-block"><h3>Habilidades</h3><textarea data-sheet-field="abilities" data-owner="'+esc(c[0])+'">'+esc(d.abilities||'')+'</textarea></div><div class="sheet-block"><h3>Histórico</h3><textarea data-char="history-'+esc(c[0])+'">'+esc(st.custom['history-'+c[0]]||'')+'</textarea></div></div><p class="subtle">Alan preenchido conforme a ficha do playtest (páginas 14–16). As demais fichas começam em branco. Alterações salvas localmente e incluídas no backup.</p>');
}


function rules(){st.investigationTab='quick';pg='investigation';investigation()}
function notes(){page('Anotações',`<div class="card"><h2>Caderno da sessão</h2><div class="field"><label>Anotações gerais</label><textarea id="notes" style="min-height:380px">${esc(st.notes)}</textarea></div></div>`)}
function settings(){page('Dados e backup',`<div class="grid"><div class="card s6"><h3>Exportar</h3><button class="btn primary" data-act="export">Exportar JSON</button></div><div class="card s6"><h3>Importar</h3><input type="file" id="file" accept="application/json"><button class="btn" data-act="import">Importar backup selecionado</button></div><div class="card s12"><h3>Reiniciar painel</h3><button class="btn" data-act="reset">Apagar dados locais</button></div></div>`)}

/* Rolador flutuante; as regras mecânicas ficam em dice-rules.js */
let dicePanelOpen=false,lastRoll=null;
function d20Icon(){return '<svg class="d20-icon" viewBox="0 0 40 40" aria-hidden="true"><path d="M20 2.8 34.8 11.4 34.8 28.6 20 37.2 5.2 28.6 5.2 11.4Z"/><path d="M20 2.8 13.4 15.2 5.2 11.4M20 2.8 26.6 15.2 34.8 11.4M5.2 11.4 13.4 24.8 5.2 28.6M34.8 11.4 26.6 24.8 34.8 28.6M13.4 15.2 26.6 15.2 26.6 24.8 13.4 24.8Z M13.4 15.2 20 37.2 26.6 15.2M13.4 24.8 20 37.2 26.6 24.8"/></svg>'}
function ensureDiceUI(){if(!document.getElementById('dice-launch')){const b=document.createElement('button');b.id='dice-launch';b.className='dice-launch';b.innerHTML=d20Icon();b.setAttribute('aria-label','Rolar dados');b.title='Rolar dados';b.onclick=()=>{dicePanelOpen=!dicePanelOpen;renderDicePanel()};document.body.appendChild(b)}}
function renderDicePanel(){
 const old=document.getElementById('dice-panel');if(old)old.remove();if(!dicePanelOpen)return;
 const p=document.createElement('div');p.id='dice-panel';p.className='dice-panel';
 p.innerHTML='<button class="dice-close" id="dice-close" aria-label="Fechar">×</button><div class="dice-heading">'+d20Icon()+'<div><h2>Rolagem de dados</h2><p class="dice-note">Escolha quantos dados rolar e o tipo de cada um.</p></div></div><div class="dice-config"><div class="dice-count-wrap"><span class="dice-section-label">QUANTIDADE</span><div class="dice-count-options">'+[2,3,4].map(n=>'<button type="button" class="dice-count-option '+(n===2?'active':'')+'" data-dice-count="'+n+'">'+n+'</button>').join('')+'</div></div><label class="dice-dt-field">DT<input id="dice-dt" type="number" value="7"></label></div><div class="dice-types-heading"><span class="dice-section-label">TIPO DE CADA DADO</span><span class="dice-note">Toque para escolher</span></div><div id="dice-types" class="dice-type-grid"></div><label class="dice-identification">Identificação (opcional)<input id="dice-label" placeholder="Personagem, perícia ou situação"></label><div class="dice-actions"><button class="btn primary" id="dice-roll">Rolar dados</button><button class="btn" id="dice-clear">Limpar</button></div><div id="dice-output" class="dice-results">'+(lastRoll?lastRoll.html:'Configure os dados e role.')+'</div>';
 document.body.appendChild(p);
 const draw=(n=2)=>{p.dataset.count=n;p.querySelectorAll('[data-dice-count]').forEach(b=>b.classList.toggle('active',+b.dataset.diceCount===n));document.getElementById('dice-types').innerHTML=Array.from({length:n},(_,i)=>'<label class="dice-type-card"><select aria-label="Tipo do dado '+(i+1)+'" data-die-type="'+i+'">'+DiceRules.types.map(d=>'<option value="'+d+'" '+(d===6?'selected':'')+'>d'+d+'</option>').join('')+'</select></label>').join('')};
 draw();p.querySelectorAll('[data-dice-count]').forEach(b=>b.onclick=()=>draw(+b.dataset.diceCount));
 document.getElementById('dice-close').onclick=()=>{dicePanelOpen=false;renderDicePanel()};
 document.getElementById('dice-clear').onclick=()=>{lastRoll=null;document.getElementById('dice-output').textContent='Configure os dados e role.'};
 document.getElementById('dice-roll').onclick=rollDiceNow;
}
function rollDiceNow(){
 const sides=[...document.querySelectorAll('[data-die-type]')].map(x=>+x.value),dt=Number(document.getElementById('dice-dt').value||7),values=sides.map(DiceRules.roll);
 const order=values.map((v,i)=>i).sort((a,b)=>values[b]-values[a]),kept=order.slice(0,Math.min(3,values.length));
 const result=DiceRules.evaluate(values,kept,dt),label=document.getElementById('dice-label').value.trim();
 const rec={id:Date.now(),date:new Date().toISOString(),label,sides,values,kept,dt,...result};
 st.rollHistory=st.rollHistory||[];st.rollHistory.unshift(rec);save();showRollResult(rec);
}

function rollCharacterTest(skill){
 const name=st.selectedCharacter||'Alan',d=getSheet(name),attr=document.getElementById('tc-attr').value,ad=Number(document.getElementById('tc-ad').value),sd=Number(document.getElementById('tc-sd').value);
 if(!ad||!sd){alert('Preencha os dados do atributo e da perícia.');return}
 const extra=Number(document.getElementById('tc-extra').value||0),ed=Number(document.getElementById('tc-ed').value||6),bonus=Number(document.getElementById('tc-bonus').value||0),dt=Number(document.getElementById('tc-dt').value||7);
 const sides=[ad,sd,...Array(extra).fill(ed)];if(sides.length>4)return;
 const values=sides.map(DiceRules.roll),order=values.map((v,i)=>i).sort((x,y)=>values[y]-values[x]),kept=order.slice(0,Math.min(3,values.length)),sum=kept.reduce((n,i)=>n+values[i],0),r=DiceRules.evaluate(values,kept,dt-bonus);
 const rec={id:Date.now(),date:new Date().toISOString(),label:name+' — '+skill,sides,values,kept,dt,bonus,total:sum+bonus,...r};rec.sum=sum;rec.success=rec.fumble?false:rec.critical?true:rec.total>=dt;rec.margin=rec.total-dt;
 st.rollHistory=st.rollHistory||[];st.rollHistory.unshift(rec);if(!rec.success){d.impeto=Math.min(3,Number(d.impeto||0)+1);saveSheet(name,d)}else save();showRollResult(rec);if(!rec.success)characters();
}
function showRollResult(r){
 const chips=r.values.map((v,i)=>'<span class="die-chip '+(r.kept.includes(i)?'keep':'')+'">d'+r.sides[i]+': <b>'+v+'</b>'+(r.kept.includes(i)?' · soma':'')+'</span>').join('');
 const status=r.fumble?'FALHA CRÍTICA':r.critical?'SUCESSO CRÍTICO':r.success?'SUCESSO':'FALHA';
 const html='<div>'+chips+'</div><p><b>'+status+'</b> · Soma: <strong>'+r.sum+'</strong> · DT: '+r.dt+'</p><p>Rolagem alta (RA): <b>'+r.high+'</b> · Rolagem baixa (RB): <b>'+r.low+'</b></p><p>'+(r.fumble?'Todos os dados foram 1. Falha automática, independentemente da DT.':r.critical?'Dois ou mais dados repetiram valor ≥ 6. Sucesso automático, independentemente da DT.':r.success?'A soma atingiu a DT.':'A soma ficou abaixo da DT.')+'</p><p class="dice-note">Os dados destacados foram somados. A regra permite somar até 3; ajuste a seleção conforme a situação.</p><div id="keep-controls">'+r.values.map((v,i)=>'<label><input type="checkbox" data-keep="'+i+'" '+(r.kept.includes(i)?'checked':'')+'> d'+r.sides[i]+' = '+v+'</label>').join('')+'</div><p id="keep-sum">Soma selecionada: '+r.sum+'</p>'+(r.fumble?'<label>Efeito adicional de falha crítica (d8)<select id="fumble-effect"><option value="">Escolher efeito</option>'+DiceRules.criticalFailureEffects.map((x,i)=>'<option value="'+(i+1)+'">'+(i+1)+' — '+x+'</option>').join('')+'</select></label>':'');
 lastRoll={record:r,html};const out=document.getElementById('dice-output');if(out)out.innerHTML=html;
}
document.addEventListener('change',e=>{
 if(e.target.dataset.keep!==undefined&&lastRoll){const idx=+e.target.dataset.keep,selected=[...document.querySelectorAll('[data-keep]:checked')].map(x=>+x.dataset.keep);if(selected.length>3){e.target.checked=false;return}lastRoll.record.kept=selected;lastRoll.record.sum=selected.reduce((a,i)=>a+lastRoll.record.values[i],0);lastRoll.record.total=lastRoll.record.sum+(lastRoll.record.bonus||0);lastRoll.record.success=lastRoll.record.fumble?false:lastRoll.record.critical?true:lastRoll.record.total>=lastRoll.record.dt;const sum=document.getElementById('keep-sum');if(sum)sum.textContent='Soma selecionada: '+lastRoll.record.sum;const i=(st.rollHistory||[]).findIndex(x=>x.id===lastRoll.record.id);if(i>=0){st.rollHistory[i].kept=selected;st.rollHistory[i].sum=lastRoll.record.sum;save()}}
 if(e.target.id==='fumble-effect'&&lastRoll){lastRoll.record.fumbleEffect=e.target.value;const i=st.rollHistory.findIndex(x=>x.id===lastRoll.record.id);if(i>=0){st.rollHistory[i].fumbleEffect=e.target.value;save()}}
});
function rollsPage(){const list=st.rollHistory||[];page('Histórico de rolagens',list.length?'<p class="subtle">Rolagens registradas neste navegador, da mais recente para a mais antiga.</p>'+list.map(r=>'<article class="roll-entry"><strong>'+esc(r.label||'Teste')+'</strong><div class="muted">'+new Date(r.date).toLocaleString('pt-BR')+'</div><p>'+r.values.map((v,i)=>'d'+r.sides[i]+': '+v).join(' · ')+'</p><p><b>'+(r.fumble?'Falha crítica':r.critical?'Sucesso crítico':r.success?'Sucesso':'Falha')+'</b> · Soma '+r.sum+' / DT '+r.dt+' · RA '+r.high+' · RB '+r.low+'</p>'+(r.fumbleEffect?'<p>Efeito: '+esc(DiceRules.criticalFailureEffects[+r.fumbleEffect-1])+'</p>':'')+'</article>').join(''):'<p class="notice">Nenhuma rolagem registrada ainda.</p>')}

function render(){({home,curse:cursePage,investigation,characters,rules,notes,settings,rolls:rollsPage}[pg]||home)()}
function go(p){pg=p;ensureDiceUI();render();document.querySelector('aside').classList.remove('open')}
document.addEventListener('click',e=>{let n=e.target.closest('[data-page]'),g=e.target.closest('[data-go]'),a=e.target.closest('[data-act]');if(n){go(n.dataset.page);return}if(g){go(g.dataset.go);return}if(e.target.closest('[data-add-char]')){const i=document.getElementById('new-char'),n=i.value.trim();if(n&&!cast.some(x=>x[0].toLowerCase()===n.toLowerCase())){cast.push([n,'Personagem']);st.selectedCharacter=n;getSheet(n);save();characters()}return}const rs=e.target.closest('[data-roll-skill]');if(rs){st.selectedSkill=rs.dataset.rollSkill;characters();return}const rc=e.target.closest('[data-roll-char]');if(rc){rollCharacterTest(rc.dataset.rollChar);return}if(e.target.closest('[data-focus]')){const n=st.selectedCharacter,d=getSheet(n);if(Number(d.pd||0)<2){alert('PD insuficiente.');return}d.pd=Number(d.pd)-2;saveSheet(n,d);const b=document.getElementById('tc-bonus');b.value=Number(b.value||0)+4;return}if(e.target.closest('[data-impeto]')){const n=st.selectedCharacter,d=getSheet(n);if(!d.impeto)return;d.impeto--;const b=document.getElementById('tc-bonus');const cfg=st.custom['test-'+n]?JSON.parse(st.custom['test-'+n]):{};cfg.bonus=Number(b?.value||0)+4;st.custom['test-'+n]=JSON.stringify(cfg);saveSheet(n,d);characters();return}const is=e.target.closest('[data-impeto-slot]');if(is){const d=getSheet(st.selectedCharacter),i=Number(is.dataset.impetoSlot);d.impeto=Math.max(0,Math.min(3,i<d.impeto?i:i+1));saveSheet(st.selectedCharacter,d);characters();return}if(!a){let tab=e.target.closest('[data-tab]'),poi=e.target.closest('[data-select-poi]');if(tab){st.investigationTab=tab.dataset.tab;save();investigation();return}if(poi){st.selected=+poi.dataset.selectPoi;save();investigation();return}return}switch(a.dataset.act){case'up':if(st.started)st.round++;break;case'down':st.round=Math.max(0,st.round-1);break;case'start':st.started=true;st.round=0;break;case'broken':st.broken=!st.broken;break;case'alive-up':st.alive=Math.min(10,st.alive+1);break;case'alive-down':st.alive=Math.max(0,st.alive-1);break;case'room':st.checks['r'+st.selected]=!st.checks['r'+st.selected];break;case'export':backup();return;case'import':document.getElementById('file').click();return;case'reset':if(confirm('Apagar os dados deste navegador?'))st={...base,checks:{},custom:{},statuses:{}};break}save();render()});
document.addEventListener('change',e=>{if(e.target.dataset.chainStep){const [ci,si]=e.target.dataset.chainStep.split('-').map(Number);st.checks['chain-manual-'+ci+'-'+si]=e.target.checked;save();investigation()}if(e.target.id==='poi-select'){st.selected=+e.target.value;save();investigation()}if(e.target.id==='chain-select'){st.chainSelected=+e.target.value;save();investigation()}if(e.target.id==='quick-select'){st.quickSelected=+e.target.value;save();investigation()}if(e.target.id==='character-select'){st.selectedCharacter=e.target.value;save();characters()}if(e.target.dataset.owner){const d=getSheet(e.target.dataset.owner),f=e.target.dataset.sheetField;if(f){d[f]=e.target.value;saveSheet(e.target.dataset.owner,d)}if(e.target.dataset.sheetAttr){d.attributes[e.target.dataset.sheetAttr]=e.target.value===''?'':Number(e.target.value);saveSheet(e.target.dataset.owner,d)}if(e.target.dataset.sheetSkill){d.skills[e.target.dataset.sheetSkill]=e.target.value===''?'':Number(e.target.value);saveSheet(e.target.dataset.owner,d)}}if(e.target.id.startsWith('tc-')){const n=st.selectedCharacter||'Alan',cfg=st.custom['test-'+n]?JSON.parse(st.custom['test-'+n]):{},m={'tc-attr':'attr','tc-ad':'ad','tc-sd':'sd','tc-dt':'dt','tc-extra':'extra','tc-ed':'ed','tc-bonus':'bonus'};cfg[m[e.target.id]]=e.target.value;st.custom['test-'+n]=JSON.stringify(cfg);save()}if(e.target.id==='room-select'){st.selected=+e.target.value;save();investigation()}if(e.target.dataset.check){st.checks[e.target.dataset.check]=e.target.checked;save();if(pg==='investigation')investigation();else render()}if(e.target.dataset.status){st.statuses[e.target.dataset.status]=e.target.value;save()}if(e.target.id==='file'&&e.target.files[0]){let f=e.target.files[0],r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);st={...base,...x,checks:{...base.checks,...x.checks},custom:{...base.custom,...x.custom},statuses:{...base.statuses,...x.statuses}};save();render();alert('Backup importado')}catch{alert('Backup inválido')}};r.readAsText(f)}});
document.addEventListener('input',e=>{let id=e.target.id;if(id==='notes')st.notes=e.target.value;else if(id==='local-note')st.custom['r'+st.selected]=e.target.value;else if(id.startsWith('desc-'))st.custom['desc'+id.slice(5)]=e.target.value;else if(e.target.dataset.clue)st.custom['clue'+e.target.dataset.clue]=e.target.value;else if(e.target.dataset.char)st.custom[e.target.dataset.char]=e.target.value;else if(e.target.dataset.owner){const d=getSheet(e.target.dataset.owner),field=e.target.dataset.sheetField;if(field){d[field]=e.target.value;st.custom['sheet-data-'+e.target.dataset.owner]=JSON.stringify(d)}}else if(e.target.dataset.note)st.custom['c'+e.target.dataset.note]=e.target.value;else if(id==='search'){st.search=e.target.value;save();let pos=e.target.selectionStart;investigation();let search=document.getElementById('search');if(search){search.focus();search.setSelectionRange(pos,pos)}return}save()});
document.getElementById('menu').onclick=()=>document.querySelector('aside').classList.toggle('open');
function backup(){let b=new Blob([JSON.stringify(st,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='backup-idolo-de-pedra.json';a.click();URL.revokeObjectURL(u)}
ensureDiceUI();render();
